/* Explanation records for sets-gaps.js — the fast route, what each wrong
   answer is built to catch, and the line to remember. The full solution is
   the question's own `expl`, so records here carry fast / traps / take. */
window.GMAT_EXPL = Object.assign(window.GMAT_EXPL || {}, {
"quant-algebra-core#1": { fast: "Move the 3x across and the 7 across in one step each: 2x = 16, x = 8. Or test (D) 8: 40 − 7 = 33 = 24 + 9 ✓.", traps: "(C) 4 is 16 ÷ 4, dividing by the wrong coefficient. (E) 16 is 2x, the last line before the division. (A) and (B) fill out the list.", take: "Collect variables on the side that keeps the coefficient positive, then check by substituting back." },
"quant-algebra-core#2": { fast: "Multiply through by 12 straight away: 4x + 3x = 168, x = 24. Never add fractions with x in them — clear them.", traps: "(A) 12 is the LCD itself. (D) 28 is 14 × 2. (E) 42 is 14 × 3. All come from doing something to 14 instead of solving.", take: "Clear every denominator in one multiplication before touching the x terms." },
"quant-algebra-core#3": { fast: "Expand, collect: 6x − 15 = 4x + 7 → 2x = 22 → x = 11. Or test (B): 3(17) = 51 = 44 + 7 ✓.", traps: "(A) 6 comes from 2x = 12, subtracting 7 instead of adding 15. (D) 22 is 2x, forgotten last division. (E) −4 is a sign slip on the 15.", take: "After expanding a bracket, re-copy the whole equation before collecting — most sign errors happen in the copy." },
"quant-algebra-core#4": { fast: "2n + 7 = 4n − 3 → 10 = 2n → n = 5. Check both phrases: 17 and 17.", traps: "(D) 10 is 2n, the un-halved line. (A) 2 comes from writing 3 − 4n on the right. (E) 12 is 7 + 5.", take: "\"More than\" adds in the order written; \"less than\" flips the order. Translate, then check against the words." },
"quant-algebra-core#5": { fast: "Three evenly spaced numbers average to the middle one: 87 ÷ 3 = 29, so the largest is 31. No variable needed.", traps: "(B) 29 is the middle integer — the right calculation stopped one step early. (A) 27 is the smallest. (D) 33 spaces by 2 from 31 as if there were four numbers.", take: "For consecutive anything, the sum divided by the count is the middle term." },
"quant-algebra-core#6": { fast: "2x + 3 is half of 4x + 6, so the answer is 26 ÷ 2 = 13. Look for the relationship before solving for x.", traps: "(A) 5 is x, the value of the variable — the question did not ask for it. (C) 10 is 2x. (D) 20 is 4x.", take: "When the question asks for an expression, check whether it is a multiple of what you were given." },
"quant-algebra-core#7": { fast: "12 ÷ (x + 2) = 3 means x + 2 = 4, so x = 2. Read a fraction equal to a number as a division fact.", traps: "(C) 4 is x + 2, not x. (A) 1 comes from 3(x + 2) = 12 solved as 3x + 2 = 12 → wrong bracket. (E) 10 is 12 − 2.", take: "Multiply both sides by the denominator, and note the value that would make it zero." },
"quant-algebra-core#8": { fast: "Strip the $20 first: $18.50 of calls at 10 cents a minute is 185 minutes.", traps: "(E) 385 divides the whole bill by 0.10 without removing the fixed charge. (A), (B), (D) are neighbours for a decimal slip.", take: "Fixed charge off first, then divide what remains by the per-unit rate." },
"quant-algebra-core#9": { fast: "Half the perimeter is length + width = 24. With length = 2w + 3: 3w + 3 = 24 → w = 7.", traps: "(D) 17 is the length — correct working, wrong quantity. (C) 12 is a quarter of 48. (B) 9 comes from 3w = 27 by dropping the +3.", take: "Name the variable after what the question asks for, and re-read the last line before you pick." },
"quant-algebra-core#10": { fast: "Multiply by 12 before expanding: 8(x − 6) = 3(x + 9) → 5x = 75 → x = 15. Or test (C): ⅔ of 9 = 6 and ¼ of 24 = 6 ✓.", traps: "(D) 18 and (B) 12 are neighbours for anyone who expanded first and slipped a sign. (A) 9 is x + 9 with x = 0.", take: "With fractions on both sides, clear them with one LCD multiplication before doing anything else." },
"quant-algebra-core#11": { fast: "Substitute y: 3x − (2x − 5) = 12 → x + 5 = 12 → x = 7. Keep the bracket until you distribute the minus.", traps: "(E) 17 is the classic sign slip: 3x − 2x − 5 = 12. (A) 5 is the constant in the y line. (C) 9 is y.", take: "When substituting an expression with a minus in front, bracket it and distribute the sign." },
"quant-algebra-core#12": { fast: "Multiply by 10: 4x + 12 = x + 30 → 3x = 18 → x = 6. Decimals are just fractions wearing a disguise.", traps: "(E) 12 is 3x, the last line before dividing. (A) 4 and (C) 5 are neighbours from a tenths slip.", take: "Clear decimals by multiplying through by a power of ten, then solve as usual." },
"quant-algebra-core#13": { fast: "An identity needs matching coefficients: 2k = 6, so k = 3. The 6s already agree.", traps: "(D) 6 matches 2k to the whole of 6x + 6 by mistake. (A) 1 and (B) 2 are k = 6 ÷ 6 or 6 ÷ 3. (E) 12 is 2 × 6.", take: "\"True for all x\" means compare coefficients, not solve for x." },
"quant-algebra-core#14": { fast: "Translate in order: 3n − 5 = n + 11, so 2n = 16 and n = 8. Check: both sides come to 19.", traps: "(E) 16 is 2n. (A) 3 is the coefficient. (D) 11 is the constant on the right. None satisfies the sentence.", take: "\"Five less than three times\" is 3n − 5; the number spoken first is subtracted." },
"quant-algebra-core#15": { fast: "40 hours = $480; the other $144 at $18/hr is 8 hours; total 48.", traps: "(E) 52 divides all $624 by $12. (A) 44 halves the overtime by using $36 as the rate. (D) 50 is a round-number guess.", take: "Split tiered pay at the tier boundary, and use the higher rate only for the hours above it." },
"quant-algebra-core#16": { fast: "Clear the fractions by multiplying through by 10: 2x − 30 = x + 10, so x = 40 in a single line.", traps: "(A) 20 comes from 2x − 30 = x + 10 → x = −20 with a dropped sign. (C) 30 and (E) 60 are the 30 and 2 × 30.", take: "Clear the fractions, then the equation is two lines long." },
"quant-algebra-core#17": { fast: "x − 4 = 10, so x = 14. Undo the division, then the subtraction.", traps: "(B) 6 adds 4 to 2 instead of to 10 — the operations undone in the wrong order. (D) 10 is x − 4. (C) 9 is 5 + 4.", take: "Undo operations in the reverse of the order they were applied." },
"quant-algebra-core#18": { fast: "Sum 45, difference 7: the smaller is (45 − 7) ÷ 2 = 19. No equation needed.", traps: "(D) 26 is the larger number — the right pair, wrong pick. (C) 22 is half the sum, ignoring the difference. (E) 38 is 45 − 7.", take: "Given a sum S and difference D, the two numbers are (S + D)/2 and (S − D)/2." },
"quant-algebra-core#19": { fast: "Turn the average into a sum: a + b = 14. Add a − b = 4 to it and b vanishes: 2a = 18, so a = 9.", traps: "(A) 5 is b. (B) 7 is the average — the number in the question, not the answer. (E) 11 is 7 + 4.", take: "An average of two numbers is a sum in disguise; convert it and use sum-and-difference." },
"quant-algebra-core#20": { fast: "Work backwards from 51: ÷3 gives 17, −9 gives 8, ÷2 gives 4.", traps: "(C) 8 is 2n, one step short. (E) 17 is 2n + 9. (D) 13 is 4 + 9.", take: "For a chain of operations ending in a known result, reverse the chain step by step." },
"quant-algebra-core#21": { fast: "Add the equations: 2x = 14, x = 7. Subtract them: 2y = 8, y = 4. The product is 7 × 4 = 28.", traps: "(E) 33 is 11 × 3, the two given numbers multiplied. (C) 24 is 6 × 4 from x = 6. (A) 14 is 2x.", take: "Sum and difference of the same two variables: add for one, subtract for the other." },
"quant-algebra-core#22": { fast: "The y terms cancel on adding: 6x = 18, x = 3, then y = 2; x + y = 5.", traps: "(A) 3 is x alone. (C) 6 is 2 × 3. (E) 18 is 6x. The question asked for the sum.", take: "When one variable's coefficients are opposites, add the equations and it disappears." },
"quant-algebra-core#23": { fast: "If all 40 were nickels the jar would hold $2.00; each dime instead adds 5 cents, and $1.25 extra ÷ 5 cents = 25 dimes.", traps: "(C) 15 is the number of nickels — the other variable. (D) 20 is half the coins. (B) 12 and (A) 10 are guesses at a round split.", take: "Coin problems are two equations: one for the count, one for the value. Work in cents." },
"quant-algebra-core#24": { fast: "Divide the first equation by 3 and it becomes the second one. Same line twice means infinitely many solutions.", traps: "(B) exactly one is the reflex for \"two equations, two unknowns\" — but the equations must be independent. (A) none would need the same slope with a different constant.", take: "Before solving a system, check whether one equation is a multiple of the other." },
"quant-algebra-core#25": { fast: "The y terms match, so subtract the equations: 2x = 8, x = 4. Then y = 2 and x − y = 2.", traps: "(C) 6 is x + y. (B) 4 is x. (D) 8 is 2x. Read which combination the question wants.", take: "Identical y terms cancel on subtraction — one line and one variable is gone." },
"quant-algebra-core#26": { fast: "Mirrored coefficients: add to get 12(x + y) = 72, so x + y = 6.", traps: "(B) 5 is x − y, from subtracting instead. (A) 4 and (D) 10 are 72 ÷ 18 and 72 ÷ 7-ish slips. (E) 12 is the coefficient.", take: "When coefficients swap places between the two equations, add or subtract before doing anything else." },
"quant-algebra-core#27": { fast: "All-adult would be $240; each child ticket saves $3; $30 saved ÷ $3 = 10 child tickets.", traps: "(E) 20 is the adult count. (C) 15 is half of 30. (D) 18 and (B) 12 fill out the list.", take: "Assume all one type, then count how many swaps it takes to reach the real total." },
"quant-algebra-core#28": { fast: "Add all three: 2(a + b + c) = 36, so a + b + c = 18; then c = 18 − (a + b) = 8.", traps: "(A) 6 is b and (E) 18 is the full sum. (C) 10 and (D) 12 are the given pair sums.", take: "Three pair sums: add them all, halve, then subtract the pair that excludes what you want." },
"quant-algebra-core#29": { fast: "Roots of x² + bx + c sum to −b: here b = −7, so the sum is 7. Never factor when only the sum is asked.", traps: "(D) 12 is the product of the roots. (E) −7 is b itself, sign not flipped. (A) 3 and (B) 4 are the individual roots.", take: "Sum of roots = −b/a, product = c/a. Check which one the question wants." },
"quant-algebra-core#30": { fast: "Product −15, sum +2: the pair is +5 and −3, so x = −5 or 3. Smaller is −5.", traps: "(C) 3 is the larger root. (B) −3 and (D) 5 are the factor constants with the wrong sign. (E) −15 is the product.", take: "The numbers you find for factoring are the negatives of the roots." },
"quant-algebra-core#31": { fast: "Move everything across: x² − 6x = 0, then factor: x(x − 6) = 0, so x = 0 or x = 6. Never divide by x.", traps: "(B) 6 only is what dividing by x produces — the root 0 is thrown away. (C) and (D) invent a −6 that nothing supports.", take: "Move everything to one side and factor; dividing by a variable can lose a root." },
"quant-algebra-core#32": { fast: "x − 3 = ±5, so x = 8 or −2, sum 6. The ± is the whole question.", traps: "(D) 8 is the positive-root-only answer. (E) 10 is 8 + 2 with the wrong sign on −2. (A) 2 is 5 − 3.", take: "Taking a square root of both sides always opens two cases." },
"quant-algebra-core#33": { fast: "(2x + 1)(x − 3) = 0 gives −½ and 3; the positive one is 3. Or test the choices: 2(9) − 15 − 3 = 0 ✓.", traps: "(A) ½ is the other root with its sign dropped. (C) 3/2 is a guess at 3 ÷ 2. (E) 5 is the middle coefficient.", take: "With a leading coefficient, try (2x ± p)(x ± q) and check the middle term." },
"quant-algebra-core#34": { fast: "One solution means a perfect square: x² + kx + 16 = (x ± 4)², so k = ±8. Positive: 8.", traps: "(B) 4 is the square root of 16 alone. (D) 16 is c. (E) 32 is 2 × 16. (A) 2 fills the list.", take: "Discriminant zero ⟺ exactly one real root ⟺ the quadratic is a perfect square." },
"quant-algebra-core#35": { fast: "Product of roots = c/a = 9/3 = 3. Two seconds, no factoring.", traps: "(E) 4 is the sum of the roots, −b/a. (B) −3 and (A) −4 have signs flipped. (C) 1 is one of the roots.", take: "c/a for the product, −b/a for the sum — divide by a first." },
"quant-algebra-core#36": { fast: "From the equation x² = 4x + 21. With x = 7 that is 49, so x² + 4 = 53. Or factor: (x − 7)(x + 3).", traps: "(C) 49 is x² without the +4. (A) 25 uses x = −3 with the sign ignored: 9 + 4 + 12. (E) 65 adds 4 to 61.", take: "When asked for an expression in x², rearrange the equation to give x² directly." },
"quant-algebra-core#37": { fast: "x² + 6x + 9 = (x + 3)². A perfect square has one repeated root, so one distinct solution.", traps: "(C) 2 is the default count for a quadratic — but the two roots coincide here. (A) 0 would need a negative discriminant.", take: "Recognise a² ± 2ab + b² on sight: it means a repeated root." },
"quant-algebra-core#38": { fast: "x + 1/x = 5/2 → 2x² − 5x + 2 = 0 → (2x − 1)(x − 2). The root above 1 is 2. Or just spot 2 + ½ = 2½.", traps: "(A) ½ is the other root, below 1. (D) 5/2 is the given sum. (B) 3/2 and (E) 3 are guesses at nearby values.", take: "A number and its reciprocal summing to k always gives a quadratic whose roots are reciprocals of each other." },
"quant-algebra-core#39": { fast: "Discriminant 25 − 28 = −3 &lt; 0, so no real roots. Do not try to factor.", traps: "(C) two is the reflex for any quadratic. (B) one would need the discriminant to be exactly 0.", take: "Check b² − 4ac before factoring; negative means stop." },
"quant-algebra-core#40": { fast: "√168 ≈ 12.96, so the pair straddles 13: 12 × 14 = 168 ✓. The larger is 14.", traps: "(C) 12 is the smaller integer. (B) 11 and (D) 13 are odd, so cannot be one of two consecutive even integers.", take: "For a product of numbers close together, the square root tells you where they sit." },
"quant-algebra-core#41": { fast: "x = ±3 and x &lt; 0 gives −3; cube it: −27. An odd power keeps the sign.", traps: "(E) 27 uses x = 3, ignoring the condition. (B) −9 is x² with a sign. (C) −3 is x, not x³.", take: "Apply the sign condition before you raise to the power, and expect an odd power to keep that sign." },
"quant-algebra-core#42": { fast: "r + s = 6, rs = 4, so r² + s² = 36 − 8 = 28. The roots are irrational — a hint not to find them.", traps: "(A) 20 is 36 − 16, doubling the product twice. (D) 36 forgets the cross term. (B) 24 is 6 × 4.", take: "r² + s² = (r + s)² − 2rs; use Vieta's sums and products, never the roots themselves." },
"quant-algebra-core#43": { fast: "A factor is zero: x − 2 = 0 gives x = 2; x + 5 = 0 gives x = −5. Only 2 is offered.", traps: "(B) −2 and (D) 5 are the roots with reversed signs. (A) −10 and (E) 10 multiply the roots together.", take: "(x − a) is zero at x = +a. Read the sign inside the bracket the opposite way." },
"quant-algebra-core#44": { fast: "Two numbers 3 apart multiplying to 130: 10 and 13. The width is the smaller, 10.", traps: "(C) 13 is the length. (E) 26 is 130 ÷ 5. (A) 8 and (D) 15 are neighbours.", take: "Area problems become quadratics; the negative root is discarded and the question usually wants the smaller dimension." },
"quant-algebra-core#45": { fast: "Let t = x²: (t − 4)(t − 9) = 0, so x² = 4 or 9, giving x = ±2, ±3 — four solutions.", traps: "(B) 2 counts the values of t rather than of x. (E) 8 doubles again for no reason. (A) and (C) fill the list.", take: "Each positive value of x² yields two values of x." },
"quant-algebra-core#46": { fast: "Roots 4 and 5 sum to 9, and the sum of roots is −b, so b = −9.", traps: "(D) 9 has the sign backwards. (E) 20 and (A) −20 are the product, already given as the constant. (C) −1 is 4 − 5.", take: "For x² + bx + c with roots r and s: b = −(r + s), c = rs." },
"quant-algebra-core#47": { fast: "(53 − 47)(53 + 47) = 6 × 100 = 600. The numbers are chosen so the sum is round.", traps: "(B) 60 and (D) 1,000 use only one of the two factors. (E) 6,000 slips a zero. (A) 6 is just the difference.", take: "Two squares subtracted: multiply their sum by their difference." },
"quant-algebra-core#48": { fast: "x² − 16 is a difference of squares: (x − 4)(x + 4). The constant in each factor is √16 = 4, never 16 ÷ 2.", traps: "(A) and (C) use 8, half of 16, instead of its square root. (D) x − 2 has no relation to 16. (E) x² + 4 would need a sum, not a difference.", take: "a² − b² = (a − b)(a + b); b is the square root of the constant." },
"quant-algebra-core#49": { fast: "(a + b)² = 64 contains the cross term 2ab = 24; strip it out and a² + b² = 64 − 24 = 40.", traps: "(D) 64 is (a + b)² with the cross term left in. (C) 52 subtracts ab once. (E) 76 adds it. (A) 28 subtracts 3ab.", take: "a² + b² = (a + b)² − 2ab — you never need a and b separately." },
"quant-algebra-core#50": { fast: "(x − 3)(x + 3) over (x − 3): cancel to x + 3. Test x = 4: 7/1 = 7 = 4 + 3 ✓.", traps: "(B) x − 3 keeps the wrong factor. (D) x + 9 divides 9 by nothing. (C) 3x and (E) x² − 3 cancel terms instead of factors.", take: "Factor first, cancel second. Only whole factors cancel." },
"quant-algebra-core#51": { fast: "(2x)² − 2(2x)(3) + 3² = 4x² − 12x + 9. Test x = 1: (−1)² = 1 and 4 − 12 + 9 = 1 ✓.", traps: "(A) 4x² − 9 squares each term and forgets the middle. (C) halves the cross term. (E) forgets to square the 2. (B) gets the middle sign of a sum.", take: "The middle term of a squared binomial is twice the product of the two terms." },
"quant-algebra-core#52": { fast: "Square it: x² − 2 + 1/x² = 9, so x² + 1/x² = 11. The cross term is −2 because x · 1/x = 1.", traps: "(A) 7 subtracts 2 instead of adding it back. (B) 9 forgets the cross term. (E) 13 adds 4.", take: "(x ∓ 1/x)² = x² + 1/x² ∓ 2. Square, then move the 2." },
"quant-algebra-core#53": { fast: "Top: (x + 2)(x + 3). Bottom: x(x + 2). Cancel (x + 2): (x + 3)/x. Test x = 1: 12/3 = 4 = 4/1 ✓.", traps: "(B) cancels the wrong factor. (C) x + 3 drops the denominator's x. (A) 3 and (E) cancel terms rather than factors.", take: "Both numerator and denominator must be fully factored before anything is cancelled." },
"quant-algebra-core#54": { fast: "(1000 − 1)(1000 + 1) = 1,000,000 − 1 = 999,999. No multiplication.", traps: "(A) 998,001 is 999². (E) 1,002,001 is 1001². (C) adds instead of subtracting the 1.", take: "Numbers equidistant from a round number are a difference of squares in disguise." },
"quant-algebra-core#55": { fast: "3(x² − 9)/(x² − 9) = 3. Pull the common factor before anything else.", traps: "(C) 9 and (D) 27 are the constants in the expression. (E) x cancels an x from nowhere. (A) 1 ignores the 3.", take: "Common factor first, always; it usually reveals a cancellation." },
"quant-algebra-core#56": { fast: "12² − 2² = 144 − 4 = 140. Or the identity: (a + b)² − (a − b)² = 4ab = 140.", traps: "(E) 144 stops at (a + b)². (B) 35 is ab. (C) 70 is 2ab. (A) 24 is 12 × 2.", take: "The difference of the two binomial squares is always 4ab." },
"quant-algebra-core#57": { fast: "x² − y² = (x + y)(x − y) = 6 × 2 = 12. The individual values (4 and 2) are never needed.", traps: "(D) 24 doubles the answer. (E) 36 is (x + y)². (A) 4 is (x − y)². (B) 8 is 6 + 2.", take: "Given a sum and a difference, x² − y² is just their product." },
"quant-algebra-core#58": { fast: "Group: x(y + 3) + 2(y + 3) = (x + 2)(y + 3). Check the xy, x and y terms against the original.", traps: "(B) swaps the constants; it expands to xy + 2x + 3y + 6. (C) and (E) get 6 as a product but the wrong middle terms. (D) is not a factorization at all.", take: "Four terms: pair them, factor each pair, and the common bracket appears." },
"quant-algebra-core#59": { fast: "Replace x with 5: 3 × 5 − 4 = 11. A function is a rule; the bracket tells you what to feed it.", traps: "(D) 15 stops at 3 × 5. (A) 7 subtracts 4 twice. (E) 19 adds instead of subtracting.", take: "Substitute the argument into every x, then follow the order of operations." },
"quant-algebra-core#60": { fast: "f(x + 1) = (x + 1)² + 1 = x² + 2x + 2. Subtract x² + 1: 2x + 1. Check at x = 3: 17 − 10 = 7 ✓.", traps: "(B) 2x drops the +1 from (x + 1)² expansion. (C) 2x + 2 forgets to subtract the 1 in f(x). (A) 1 subtracts only the constants.", take: "Substitute the whole argument in brackets, expand, then subtract carefully." },
"quant-algebra-core#61": { fast: "Inside first: g(2) = 7, then f(7) = 49. Composition reads right to left.", traps: "(B) 11 is g(f(2)) = g(4) — the reverse order. (A) 7 is g(2) alone. (C) 25 squares the wrong number.", take: "f(g(x)): evaluate g, then hand the result to f." },
"quant-algebra-core#62": { fast: "Substitute literally: 4 × 3 − 4 + 3 = 11. The symbol means nothing beyond its definition.", traps: "(C) 13 is 3 ◊ 4, the order swapped. (A) 5 subtracts both. (D) 19 adds both.", take: "Made-up operations are not commutative unless the definition is symmetric — respect the order." },
"quant-algebra-core#63": { fast: "4 ◊ 3 = 11 and 3 ◊ 4 = 13, so the difference is −2. In general a ◊ b − b ◊ a = 2(b − a).", traps: "(C) 0 assumes the operation commutes. (E) 2 has the subtraction the wrong way round. (B) and (D) are half-steps.", take: "Compute each side of a custom operation separately before combining them." },
"quant-algebra-core#64": { fast: "f(3) = 5, then f(5) = 9. Apply the rule twice, one number at a time.", traps: "(A) 5 stops after one application. (D) 11 adds 1 instead of subtracting on the second pass. (B) 7 is 2 × 3 + 1.", take: "f(f(x)) means feed the output straight back in as the new input." },
"quant-algebra-core#65": { fast: "The root needs x ≥ 4 (all pass); the denominator needs x ≠ 6. So 6 is out.", traps: "(A) 4 looks suspicious but √0 = 0 is fine in a numerator. (D) 7 and (E) 10 are safely inside the domain.", take: "Domain = every restriction at once: nothing negative under an even root, nothing zero under a fraction bar." },
"quant-algebra-core#66": { fast: "Slope a = (11 − 5)/(3 − 1) = 3; then b = 5 − 3 = 2, and f(0) = b = 2.", traps: "(D) 3 is the slope a. (E) 8 is f(2). (A) −1 subtracts the wrong way round.", take: "For a linear function, two values give the slope, and f(0) is the intercept b." },
"quant-algebra-core#67": { fast: "19 steps of 4 on top of 5: 5 + 76 = 81. It is (n − 1) steps to reach the nth term.", traps: "(D) 85 takes 20 steps — the fencepost error. (A) 76 forgets the first term. (B) 80 and (E) 89 are neighbours.", take: "a_n = a_1 + (n − 1)d; the first term is where you start, not a step." },
"quant-algebra-core#68": { fast: "Average the first and last terms, (5 + 81)/2 = 43, and multiply by the 20 terms: 860.", traps: "(E) 1,620 forgets to halve. (A) 800 uses 40 as the average. (B) 840 and (D) 880 are ±20.", take: "An arithmetic sum is (first + last)/2 × count — never add the terms." },
"quant-algebra-core#69": { fast: "The 8th term needs seven doublings of the first: 3 × 2⁷ = 3 × 128 = 384.", traps: "(E) 768 doubles eight times. (C) 256 drops the leading 3. (B) 192 doubles six times.", take: "For a geometric sequence the nth term uses r^(n−1): one fewer multiplication than n." },
"quant-algebra-core#70": { fast: "From 4 to 94 is 90, which is 30 steps of 3 — and 30 gaps means 31 terms. Count posts, not gaps.", traps: "(A) 30 is the number of gaps. (C) 32 adds one too many. (D) and (E) fill the list.", take: "Terms = (last − first)/d + 1. The +1 is the most-missed step in the topic." },
"quant-algebra-core#71": { fast: "3 → 5 → 9 → 17 → 33. Each term is one less than double the previous. Note the pattern 2^n + 1.", traps: "(A) 17 is a_4. (E) 65 is a_6. (C) 31 is 2^5 − 1, the wrong offset. (B) 25 is 33 − 8.", take: "For a short recursion, generate the terms — it is faster than finding a formula." },
"quant-algebra-core#72": { fast: "2 → −1 → ½ → 2: period 3. 100 = 3 × 33 + 1, so a_100 = a_1 = 2.", traps: "(A) −1 is a_2 (remainder 2). (B) ½ is a_3 (remainder 0). (C) 1 and (E) 3 never occur.", take: "Recursive sequences on the exam almost always cycle; find the period and take a remainder." },
"quant-algebra-core#73": { fast: "Use n(n + 1)/2 with n = 50: 50 × 51 / 2 = 1,275. Or average 25.5 times 50 terms.", traps: "(E) 2,550 forgets to halve. (A) 1,225 is 50 × 49/2. (B) 1,250 is 25 × 50.", take: "1 + 2 + … + n = n(n + 1)/2." },
"quant-algebra-core#74": { fast: "50 even numbers averaging 51: 2,550. Or double the sum 1 to 50.", traps: "(E) 5,050 sums every integer to 100. (A) 2,500 uses average 50. (D) 5,000 doubles that.", take: "Evenly spaced sets: average the ends, multiply by the count." },
"quant-algebra-core#75": { fast: "Five steps cover 15, so d = 3; two steps back from 11 gives 5.", traps: "(D) 8 goes back one step only. (A) 2 goes back three. (E) 14 goes forward.", take: "Distance between two terms = (difference in position) × d; count positions, not values." },
"quant-algebra-core#76": { fast: "3 × 55 + 2 × 10 = 165 + 20 = 185. Or first 5, tenth 32, average 18.5, × 10.", traps: "(B) 165 forgets the ten 2s. (C) 175 adds only five of them. (E) 195 adds twenty.", take: "Split a sum of a linear formula into the n-part and the constant part." },
"quant-algebra-core#77": { fast: "Rise over run: (11 − 2)/(4 − 1) = 9/3 = 3. Subtract in the same order on top and bottom.", traps: "(E) 9 is the rise alone. (D) 4 is the x-coordinate. (A) 1 and (B) 2 fill the list.", take: "Slope = (y₂ − y₁)/(x₂ − x₁), subtracting in the same order on top and bottom." },
"quant-algebra-core#78": { fast: "The x-intercept is where y = 0: 0 = −2x + 8 gives 2x = 8, so x = 4.", traps: "(E) 8 is the y-intercept. (B) −4 keeps the wrong sign. (C) 2 is the slope's magnitude.", take: "x-intercept: y = 0. y-intercept: x = 0." },
"quant-algebra-core#79": { fast: "Average x: (−3 + 7)/2 = 2. Average y: (5 − 1)/2 = 2. Midpoint (2, 2).", traps: "(C) (5, 3) halves the gaps instead of averaging. (B) (4, 4) uses the sums without halving one coordinate. (E) keeps the −3.", take: "Midpoint = average of the x's and average of the y's." },
"quant-algebra-core#80": { fast: "The gaps are 3 across and 4 up — the classic 3-4-5 triple, so the distance is 5 with no root to take.", traps: "(D) 7 adds the gaps. (E) √7 adds them under the root. (A) 3 and (B) 4 are the legs.", take: "Distance is Pythagoras on the horizontal and vertical gaps; recognise 3-4-5." },
"quant-algebra-core#81": { fast: "Perpendicular slope −⅓; from (6, 2), going left 6 raises y by 2: intercept 4.", traps: "(E) 20 uses slope +3. (B) 2 is the given y. (A) −2 uses slope +⅓. (D) 6 is the given x.", take: "Perpendicular slopes multiply to −1; then walk from the known point to x = 0." },
"quant-algebra-core#82": { fast: "Positive slope, positive intercept: the line lives in II, I and III. Quadrant IV needs x &gt; 0 with y &lt; 0, which never happens.", traps: "(C) III is where the line goes once x &lt; −1.5. (E) all four is impossible for any line with positive slope and positive intercept.", take: "Sketch the two intercepts; the quadrant the line misses is the one on the far side of both." },
"quant-algebra-core#83": { fast: "Total 60; four others at the minimum 4 each = 16; largest 44.", traps: "(E) 56 sets three of the others to 0. (C) 48 uses three 4s. (A) 40 uses five 4s.", take: "Maximise one value by minimising all the others, respecting every constraint." },
"quant-algebra-core#84": { fast: "Test the four corners: (−4)(−2) = 8, (−4)(5) = −20, (3)(−2) = −6, (3)(5) = 15. Largest is 15.", traps: "(A) 8 assumes the negative corner wins. (D) 20 is the magnitude of the most negative product. (E) 35 multiplies the ranges' widths.", take: "Products over ranges: check all four corner pairs, not just the positive one." },
"quant-algebra-core#85": { fast: "Most negative pairs the most negative x with the most positive y: (−4)(5) = −20.", traps: "(D) −6 and (C) −8 use the wrong endpoints. (E) 8 is a positive corner.", take: "Least product = most negative × most positive." },
"quant-algebra-core#86": { fast: "Negative squared is positive; negative cubed stays negative; reciprocal keeps the sign. All three hold for every negative x.", traps: "(C) drops III on the belief that 1/x flips sign — it does not. (A) and (B) miss the other sure statements.", take: "Even powers erase the sign, odd powers and reciprocals keep it." },
"quant-algebra-core#87": { fast: "Allowed integers −2 to 2; x² − x is largest at x = −2: 4 + 2 = 6.", traps: "(A) 2 tests only x = 2. (D) 9 uses x = 3, which |x| &lt; 3 forbids. (E) 12 uses x = −3.", take: "List the allowed integers and evaluate each — the negative end often wins." },
"quant-algebra-core#88": { fast: "Complete the square: x² − 6x + 13 = (x − 3)² + 4. A square is never below 0, so the minimum is 4, at x = 3.", traps: "(A) 3 is where the minimum happens, not the value. (D) 13 is the value at x = 0. (E) −5 subtracts 9 twice.", take: "For ax² + bx + c with a &gt; 0, the minimum is at x = −b/2a; substitute to get the value." },
"quant-algebra-core#89": { fast: "Distinct means the others are at least 1, 2, 3 — total 6 — so the largest is 24.", traps: "(D) 27 uses 1, 1, 1, which are not distinct. (E) 29 uses only one other. (A) 20 subtracts 10.", take: "\"Distinct\" forces the minimised values to step up: 1, 2, 3, …" },
"quant-algebra-core#90": { fast: "x = −1 kills II and III at once. Only I survives every nonzero x.", traps: "(E) all three forgets negatives exist. (D) keeps III, which is x &gt; 0 rewritten. (B) picks the one that fails.", take: "x ≠ 0 does not mean x &gt; 0 — always test a negative." },
"quant-algebra-core#91": { fast: "Fixed sum: the product is smallest when the numbers are furthest apart — 1 and 9.", traps: "(E) 25 is the greatest product (5 and 5). (D) 24 and (C) 21 are middle pairs.", take: "For a fixed sum, product is maximised by equal parts and minimised by the most unequal split." },
"quant-algebra-core#92": { fast: "Split the fraction: (x + y)/y = 1 + x/y. Push x to 8 and y to 1 for the largest ratio: 1 + 8 = 9.", traps: "(A) 3 uses smallest x over largest y — the minimum. (E) 12 adds x and y. (C) 8 forgets the +1.", take: "Simplify the expression before pushing to the edges; a fraction's max comes from max top over min bottom." },
"quant-numberline-ex#1": { fast: "Among negatives, the biggest-looking digit is the smallest number: −3 is furthest left.", traps: "(C) −0.9 is the greatest of the negatives, the common reversal. (A) −2.5 and (E) −2 sit between. (D) 0 is the largest of all.", take: "Negative numbers: further from zero means smaller." },
"quant-numberline-ex#2": { fast: "Drop the signs and compare distances: 0.4, 0.45, 0.375, 0.4, 0.36 — the smallest is 0.36.", traps: "(C) −3/8 = −0.375 is close but not closest. (A) −0.4 is the \"smallest number\", which is a different question. (B) 0.45 is the furthest away.", take: "Closest to zero = smallest absolute value, sign ignored." },
"quant-numberline-ex#3": { fast: "For x = ½: ½, ¼, 0.71, 2, ⅛. Only the reciprocal escapes above 1.", traps: "(C) √x is the largest of the ones that stay below 1. (B) and (E) shrink the number. (A) x itself sits in the middle.", take: "Between 0 and 1: powers shrink, roots grow toward 1, the reciprocal jumps above 1." },
"quant-numberline-ex#4": { fast: "For x = −½: −½, ¼, −⅛, −2, ½. The reciprocal of a number between −1 and 0 is below −1.", traps: "(A) x looks least but is only −½. (C) x³ is closer to zero than x. (B) and (E) are positive.", take: "Reciprocals of numbers between −1 and 0 are less than −1." },
"quant-numberline-ex#5": { fast: "Within 4 of 3 means −1 &lt; n &lt; 7; the integers 0 through 6 are seven.", traps: "(E) 9 counts the endpoints −1 and 7, excluded by the strict inequality. (D) 8 includes one of them. (A) 5 and (B) 6 miscount.", take: "Strict inequality excludes the endpoints; count inclusively only for ≤." },
"quant-numberline-ex#6": { fast: "Distance is |5 − (−7)| = 12: seven units from −7 up to zero, then five more to 5.", traps: "(A) 2 subtracts the digits as if both were positive. (C) 7 and (B) 5 are the two halves. (E) 35 multiplies.", take: "Distance on the line is |a − b|; across zero, add the two distances to zero." },
"quant-numberline-ex#7": { fast: "x = −3, y = −1: 9 &gt; 1, −⅓ &gt; −1, 3 &gt; 1. All three, and no pair of negatives breaks any of them.", traps: "(C) drops II because reciprocals seem to preserve order — for two same-sign numbers they reverse it, which is what II says. (D) drops I.", take: "Two negatives: the one further from zero has the bigger square, bigger absolute value, and the reciprocal closer to zero." },
"quant-numberline-ex#8": { fast: "The window is 0.4 to 0.5. 3/7 ≈ 0.43 is the only choice inside it.", traps: "(A) 1/3 and (E) 3/10 sit below 0.4. (C) 4/7 and (D) 5/8 sit above 0.5.", take: "Convert to decimals to two places and compare against the window's ends." },
"quant-numberline-ex#9": { fast: "x − y runs from just above −2 to just below 6. Only 5 is inside.", traps: "(B) −2 and (D) 6 are the endpoints, which strict inequalities never reach. (A) −3 and (E) 8 are outside altogether.", take: "For x − y, subtract the opposite ends — and keep the strict/loose nature of the bounds." },
"quant-numberline-ex#10": { fast: "Convert each: 1/3 = 0.333… is the only value strictly inside 0.3 to 0.35; two choices sit exactly on the ends.", traps: "(B) 3/10 and (E) 7/20 equal the endpoints — \"between\" excludes them. (C) 3/8 = 0.375 is above. (D) 2/7 is below.", take: "Check whether a choice equals an endpoint before counting it as between." },
"quant-numberline-ex#11": { fast: "x = 1/x means x² = 1, so x = 1 or x = −1 — the only numbers equal to their own reciprocal. Sum 0.", traps: "(D) 1 forgets the negative solution. (E) 2 adds 1 twice. (B) −1 is the other root alone.", take: "Squaring hides a sign; a number equal to its own reciprocal is 1 or −1." },
"quant-numberline-ex#12": { fast: "y − x is positive minus negative: always positive and bigger than both. Test −2 and 3: 5 beats 1, −5, −6, −0.67.", traps: "(E) x + y can be positive but never exceeds y. (A), (C) and (D) are always negative when x &lt; 0 &lt; y.", take: "Subtracting a negative adds its size; y − x is the largest combination of a negative and a positive." },
"quant-numberline-ex#13": { fast: "0.005 × 2,500 = 12.5. The choices are powers of ten apart, so the rough product decides it.", traps: "(D) 120 and (B) 1.2 are the neighbours for a misplaced decimal. (E) 1,200 multiplies 0.48 instead of 0.0048.", take: "When choices differ by factors of ten, estimate the size and stop." },
"quant-numberline-ex#14": { fast: "Decimals: 6 × 3 ≈ 18. Exponents: 10⁴ × 10⁻² = 10². So about 18 × 10² = 1.8 × 10³ after renormalising.", traps: "(A) keeps 17.7 × 10² without renormalising. (C) 10⁴ adds the exponents as 4 + 2. (D) and (E) drift further.", take: "Multiply the decimals, add the exponents, then push the decimal back into 1–10." },
"quant-numberline-ex#15": { fast: "Bracket with perfect squares: 81 &lt; 82 &lt; 100, so 9 &lt; √82 &lt; 10 — and barely above 9, since 82 is just past 81.", traps: "(E) 40 and 41 halve instead of rooting. (B) 8 and 9 misplaces 82 below 81. (D) 10 and 11 would need 82 above 100.", take: "Bracket a root between the two nearest perfect squares." },
"quant-numberline-ex#16": { fast: "3,000 × 51 / 150 = 20 × 51 = 1,020. Rounding both up keeps the errors cancelling.", traps: "(B) 510 divides by 300. (D) 5,100 divides by 30. (A) and (E) are further slips of ten.", take: "Round a numerator and denominator in the same direction and the errors offset." },
"quant-numberline-ex#17": { fast: "10⁸ moves the point eight places: 470,000,000 — nine digits.", traps: "(B) 8 counts the exponent. (D) 10 counts 4.7 as two digits plus eight. (A) 7 and (E) 11 are off by two.", take: "a × 10ⁿ with 1 ≤ a &lt; 10 has n + 1 digits." },
"quant-numberline-ex#18": { fast: "Split it: 8.4 ÷ 2.1 = 4, and 10⁵ ÷ 10⁸ = 10⁻³. Put them back together: 4 × 10⁻³ = 0.004.", traps: "(E) 400 subtracts the exponents the wrong way. (C) 0.04 and (A) 0.0004 are one power off. (D) 4 ignores the exponents.", take: "Dividing powers of ten subtracts exponents: top minus bottom." },
"cr-except#1": { fast: "Checklist: cross out everything that weakens. Prices (A), a rival closing (B), a city-wide rise (C), cards going to regulars (D) all do. Only the card's cost (E) is silent on customers.", traps: "(A), (B) and (C) each give a rival cause for the revenue rise. (D) attacks the \"new customers\" claim head-on — the strongest weakener, and the most tempting pick for anyone who forgot the flip.", take: "The EXCEPT answer is usually the choice with no effect at all, not the opposite effect." },
"cr-except#2": { fast: "Four choices tighten the link from breakfast to weight; one is about advertising. Advertising (C) is the exception.", traps: "(A) is the randomized trial — the best strengthener, so the worst pick here. (D) rules out exercise as the hidden cause. (B) and (E) give mechanisms.", take: "On a strengthen-EXCEPT, the strongest strengthener is the wrongest answer." },
"cr-except#3": { fast: "Every choice that gives a reason the road will not cut congestion goes. The contractor's identity (A) gives no such reason.", traps: "(B) induced demand and (E) the failed twin are classic plan-weakeners. (C) says the bottleneck is elsewhere. (D) says the road will be empty.", take: "A plan is doubted only by facts about whether it reaches its goal; facts about who builds it are noise." },
"cr-except#4": { fast: "Cheap umbrellas, sun umbrellas, a heat wave, more people — four explanations. Rain at night (D) explains nothing about buying umbrellas.", traps: "(B) and (C) work together and are the most likely to be doubted, but each gives people a reason to buy. (E) is pure numbers: 20 percent more people, 20 percent more sales.", take: "In an explain-EXCEPT, a choice that makes the puzzle stranger is a fine answer." },
"cr-except#5": { fast: "Useful questions test whether productivity will rise; the executive's taste (B) tests nothing.", traps: "(D) looks off-topic but customers lost on the fifth day would cut output — it is useful. (A), (C), (E) go straight to the mechanism.", take: "Evaluate-EXCEPT: the answer is the question whose yes and no would leave the conclusion exactly where it was." },
"cr-except#6": { fast: "Fewer passengers, hidden form, weather routes, complaint-prone travellers — four reasons complaint counts mislead. Same aircraft (C) makes the comparison fairer, if anything.", traps: "(A) is the base-rate weakener and the strongest. (E) is easy to misread as strengthening — it explains Y's complaints away from service, which weakens.", take: "A choice that makes two things more comparable does not weaken a comparison between them." },
"cr-except#7": { fast: "Control group, timing, mechanism, dose-response — four ways to say fluoride did it. Equal check-up prices (E) say nothing about cause.", traps: "(A) is the strongest strengthener. (D) dose-response is the one students most often miss as a strengthener.", take: "Money facts that do not touch the causal chain are the standard neutral answer." },
"cr-except#8": { fast: "LEAST support: taste (A) has no connection to relief. The other four are the textbook evidence set for a drug.", traps: "(B) placebo control is the strongest support. (C), (D), (E) each add a separate pillar. Any of them chosen means the LEAST was read as MOST.", take: "LEAST questions are EXCEPT questions in disguise — flip the task before reading the choices." },
"cr-except#9": { fast: "Unrepresentative sample, self-report, January timing, dawn-only respondents — all weaken. Three branches (D) does not change who was surveyed.", traps: "(A) is the core sampling flaw. (E) is a second sampling flaw inside the first. (B) and (C) attack the data rather than the sample — still weakeners.", take: "For a survey argument, weakeners attack the sample or the measurement; a fact about the organisation does neither." },
"cr-except#10": { fast: "More patients, untrained hires, an extra step, a closed clinic — four reasons for longer waits. Pay (B) affects the budget, not the queue.", traps: "(C) is the subtle one: more nurses on paper, not in practice. (A) and (E) are demand-side explanations.", take: "Explaining a queue is about arrivals and service capacity; anything else is the exception." },
"cr-except#11": { fast: "Other cause, wrong kind of factory, missing culture, failed elsewhere — four ways to break the analogy. A publication date (C) leaves it intact.", traps: "(A) removes Toyota's gain as evidence. (B) and (D) deny the comparison. (E) is the statistical weakener.", take: "Arguments by analogy are weakened by any relevant difference; history of the idea is not one." },
"cr-except#12": { fast: "Easy cuts, a successful pilot, stated intentions, a rate that bites — four supports. Where the water comes from (A) is background.", traps: "(E) is easy to misjudge: if most households would face the higher rate, the incentive reaches most of the use — support. (C) is the strongest.", take: "Support for a plan means evidence that its mechanism will operate; sourcing facts are not that." },
"cr-except#13": { fast: "Same output, higher foreign share: more abroad, less at home, abroad beats home, up 15 points. Revenue (D) needs prices, which are never given.", traps: "(C) 55 versus 45 is inferable and often doubted. (E) is arithmetic on the shares. (A) and (B) follow from a fixed total.", take: "Inference-EXCEPT: the exception is the choice that needs a fact the passage never supplies." },
"cr-except#14": { fast: "Motivation, a grade filter, reverse causation, easier subjects — all explain the correlation without the tutoring causing it. The floor of the library (B) explains nothing.", traps: "(D) reversed causation is the one most often mistaken for a strengthener. (C) is a selection effect. (A) and (E) are hidden third variables.", take: "Correlation-to-cause arguments are weakened by any alternative story; location is not a story." },
"rc-ss-impressionism#4": { fast: "Scan for evaluative words: \"far-reaching\", \"profoundly revolutionary\". Respectful analysis, not hostility or irony.", traps: "(C) reads condemnation into the exclusion of emotion, which is only reported. (D) mistakes the painters' disavowal of philosophy for the author's mockery. (A) and (E) import attitudes the text never shows.", take: "Tone lives in the adjectives the author chooses, not in the facts reported." },
"rc-ss-impressionism#5": { fast: "Four paragraphs: claim, contrast with the Greek view, elaboration, consequences. Only (A) follows that order.", traps: "(B) and (C) invent a debate; nothing is disputed. (E) promotes the quotations from support to subject.", take: "For organisation questions, label each paragraph's job in three words and match the sequence." },
"rc-ss-blackhole#3": { fast: "Opens with a question, offers dynamical evidence, ends on a \"serious problem\". Question–evidence–difficulty is (C).", traps: "(A) calls the evidence confirming when the passage calls it inconclusive. (D) needs two explanations; there is one.", take: "A passage that ends on a problem is organised around a difficulty, not a confirmation." },
"rc-ss-blackhole#4": { fast: "\"Seemingly this should be a black hole, but…\" — provisional acceptance plus a reservation is (C).", traps: "(A) drops the reservation. (B) drops the acceptance. (E) invents enthusiasm the flat prose never shows.", take: "Hedges plus a \"but\" mean tentative; pick the answer that keeps both halves." },
"rc-ss-14thamend#3": { fast: "\"Unjustifiably vetoed\" is a verdict in one adverb: disapproval.", traps: "(A) neutral is the default guess, but a passage that calls an act unjustifiable is not neutral. (D) ambivalent needs a second opinion that never appears.", take: "One evaluative adverb settles a tone question; find it before reading the choices." },
"rc-ss-australopith#3": { fast: "Evidence (Lucy's bones), then a question (\"what advantage…?\"), then a theory. That is (B).", traps: "(A) inverts the paragraph's role. (D) treats the chimpanzee comparison as the point rather than as support.", take: "A paragraph that ends by answering a question it raised is doing two jobs; the right choice names both." },
"rc-ss-australopith#4": { fast: "\"One theory is\" and \"According to this view\" attribute the idea rather than asserting it. Neutral report, (C).", traps: "(B) is the tempting over-read: presenting a theory is not endorsing it. (A) needs a rejection that never comes.", take: "Attribution words (\"one theory\", \"according to\") signal a reported view, not the author's." },
"rc-g1-04#9": { fast: "Benevolence \"little better\" than maltreatment: a bleak verdict with a twist of phrase. Wry pessimism.", traps: "(A) and (E) read the sentence backwards. (D) misses the irony — clinical prose does not balance benevolence against maltreatment.", take: "Irony plus a negative verdict reads as wry, not detached." },
"rc-g1-08#19": { fast: "Paragraph 1: what the laws were meant to do. Paragraph 2, with \"however\": what they actually did. Opposite result — (D).", traps: "(A) describes the intention, not the outcome. (E) invents a recommendation.", take: "\"However\" at the top of a paragraph usually means the paragraph reverses what came before." },
"rc-700-birds#3": { fast: "The author rebuts each objection but calls one \"reasonable when…\" and admits another cannot be settled. Disagreement with concessions.", traps: "(A) ignores the concessions. (C) ignores the rebuttals. Both halves are in the text.", take: "When an author concedes and rebuts, the tone answer must contain both a \"but\" and a \"grants\"." },
"rc-700-birds#4": { fast: "Position, then \"They argue… Skeptics also argue… Finally, some scientists argue\" — three objections, each answered. (A).", traps: "(B) and (E) need two theories or a test; the passage has one position and three replies.", take: "Count the signposts — \"also\", \"finally\" — to see how many objections are handled." },
"rc-700-sanandreas#4": { fast: "Anomaly (less heat), explanation (clay), test (Byerlee) fails, new idea (water). Only (C) has the failed test in the middle.", traps: "(B) presents clay and water as rivals side by side; in the passage one is dismissed before the other appears.", take: "Look for the verb that kills an explanation (\"found that… as much friction as\") — it marks the turn." },
"rc-700-hopi#4": { fast: "\"But equally important … may have been\" adds a factor without removing the old ones. Valid but incomplete.", traps: "(A) and (D) read \"but\" as rejection; \"equally\" shows it is addition. (E) ignores that proposing an addition is itself a view.", take: "\"Equally important\" keeps the earlier claims and supplements them." },
"rc-700-housework#4": { fast: "An idea \"remained largely unchallenged until\" two scholars — then each scholar's challenge. (A).", traps: "(B) contrasts Vanek and Cowan, but the passage presents them as allies against the same idea. (D) needs a reaffirmation that never comes.", take: "\"Until X and Y\" introduces challengers; expect the rest to summarise their work." },
"rc-700-housework#5": { fast: "The passage calls their works \"groundbreaking and influential\" — two words of praise, so the attitude is admiring.", traps: "(C) neutral fails on those two adjectives. (E) ambivalent needs a reservation; there is none.", take: "Adjectives attached to a scholar's name are the author's evaluation of that scholar." },
"rc-ss-seals#2": { fast: "Paragraph 1 ends on a surprise; paragraph 2 begins \"may, however, have to do with\" — an explanation of it. (B).", traps: "(E) mistakes the supporting list for the purpose. (D) over-reads the final size comparison.", take: "A paragraph opening with \"may have to do with\" is explaining what came just before." },
"rc-ss-seals#3": { fast: "\"Until recently… believed\" plus \"surprisingly found\": the old assumption is now in question.", traps: "(B) misses that the passage reports the assumption's failure. (A) reads scorn into a neutral account.", take: "\"Until recently\" marks a view the author considers superseded." },
"rc-g1-12#30": { fast: "The last line vindicates White, whose view is that even secondary human responsibility is unsupported. Martin's theory is therefore undermined.", traps: "(E) reverses the final sentence. (C) ignores it. (D) invents a partial rescue.", take: "In a passage with several scholars, the author's verdict is usually in the last sentence — read it first." },
"di-msr-venue#1": { fast: "Four tests, four venues. Civic fails rooms, Riverside is booked (and over budget), Summit is too small. Harbour Hall alone passes.", traps: "(B) Civic Centre is roomy and cheap but has two breakout rooms. (D) Summit Suites has the rooms but holds 220. (C) Riverside is unavailable.", take: "Check every requirement for every candidate; one failure eliminates." },
"di-msr-venue#2": { fast: "$9,500 plus 250 × $20 in-house catering = $14,500. The $35 rate is for the other venues.", traps: "(E) $18,250 applies the $35 outside rate to Harbour Hall. (A) $9,500 forgets catering. (D) $17,500 uses $32.", take: "Read which source's rate applies to which venue before multiplying." },
"di-msr-venue#3": { fast: "Only one venue passed all four tests in question 1 — that is (C). The other four statements each fail a quick number check.", traps: "(D) $12,400 is over the $12,000 budget. (E) 20 is not less than half of 35. (A) 220 × 35 = 7,700 is under 8,000.", take: "For must-be-true, test each statement against the numbers rather than against impressions." },
"di-msr-venue#4": { fast: "Without the room rule, Harbour and Civic qualify. Harbour 14,500 versus Civic 5,500 + 8,750 = 14,250. Civic wins by $250.", traps: "(A) Harbour Hall wins on venue rate alone but loses once outside catering at Civic is still cheaper overall. (D) Summit still fails on capacity.", take: "Cheapest means total cost; a cheap venue with expensive catering can still win." },
"di-msr-recall#1": { fast: "Batch B7 is 10 percent of each region's shipment; the East received 15,000, so 1,500 are defective.", traps: "(B) 1,000 uses East's sold figure from Source 3. (C) 1,200 uses North's shipped figure. (E) 2,000 is West's sold figure.", take: "Match the percentage to the base it was stated against — shipped, not sold." },
"di-msr-recall#2": { fast: "4,000 defective, 60% returned = 2,400, × $15 = $36,000, + $20,000 notices = $56,000.", traps: "(A) $36,000 omits the fixed notice cost. (E) $80,000 refunds all 4,000. (D) $60,000 refunds 4,000 at $15 without notices.", take: "Assemble a cost from the sources in order: units, rate, share returned, then fixed costs." },
"di-msr-recall#3": { fast: "29,000 of 40,000 units are sold, so 72.5% of the evenly spread defects are already out there. (A) is true.", traps: "(C) North's 3,000 unsold is less than East's 5,000. (B) West sold 2,000 of 5,000. (D) and (E) contradict the $36,000 and 2,400 figures.", take: "\"Spread evenly\" lets you apply the overall sold share to the defective units." },
"di-msr-recall#4": { fast: "10% of the 29,000 sold are defective: 2,900, × $15 = $43,500.", traps: "(D) $60,000 refunds every defective unit, sold or not. (A) $36,000 is the original 60% scenario. (C) $45,000 uses 3,000.", take: "When the scenario changes the return rule, recompute the base before multiplying." },
"di-msr-rooms#1": { fast: "3 rooms × 6 slots = 18; R2 loses its three afternoon slots; 15 remain.", traps: "(D) 18 ignores the closure. (A) 12 removes a whole room. (C) 16 removes only two slots.", take: "Count the slots a closure actually removes — from 2 p.m. means 2–4, 4–6 and 6–8." },
"di-msr-rooms#2": { fast: "R2 is closed at 2 p.m. and Priya already holds two slots. Two separate blocks — (D).", traps: "(B) and (C) each spot only one of the two reasons. (A) misses both.", take: "When a question offers \"only because\" options, check whether more than one rule applies." },
"di-msr-rooms#3": { fast: "Nine bookings listed (4 + 2 + 3) out of 15 available slots: six unbooked.", traps: "(E) 9 is the number of bookings. (D) 7 subtracts from 16. (B) 5 counts R2's closed slots as booked.", take: "Unbooked = available minus booked; get both counts from the right sources." },
"di-msr-rooms#4": { fast: "At 2–4, R1 and R3 are held by individuals and R2 is shut. Groups of three or more outrank individuals, so the group can take R1 or R3.", traps: "(A) forgets the priority rule. (C) sends the group to a closed room. (D) moves them to a slot that is also an individual booking, which changes nothing.", take: "Policy rules in one source decide what the bookings in another source allow." },
"di-gi-revenue#1": { fast: "Q1 is 40 and Q4 is 65: a rise of 25 on a base of 40, and 25/40 = 62.5 percent.", traps: "(B) 37.5% divides by the end value. (A) 25% reports the raw change. (E) 75% is 30 ÷ 40.", take: "Percent change always uses the starting value as the base." },
"di-gi-revenue#2": { fast: "Add the four bars for the year: 40 + 50 + 45 + 65 = 200. Q4 is 65 of that, and 65/200 = 32.5%.", traps: "(A) 25% assumes four equal quarters. (D) 35% rounds up. (E) 40% is the Q1 figure read as a percent.", take: "Share of total: add every bar first, then divide." },
"di-gi-revenue#3": { fast: "50 → 45 is down 5 on 50: decreased by 10 percent. Direction first, then size.", traps: "(E) 11.1% divides by the later quarter. (C) 5% reports the absolute drop. (A) has the wrong direction.", take: "Fill a drop-down by direction before magnitude, and measure against the earlier value." },
"di-gi-revenue#4": { fast: "Sort the four values: 40, 45, 50, 65. With an even count, average the middle two: (45 + 50)/2 = 47.5.", traps: "(C) 50 is the mean and also one of the middle values — the classic median trap. (A) 45 is the other middle value.", take: "Even count: the median is the average of the two middle values, which need not be a data point." },
"di-gi-temps#1": { fast: "Steepest rising segment: April to May, +6. The others are +4 or +3.", traps: "(B) March to April is +4. (D) May to June is +4. (E) June to July is only +3.", take: "Compare slopes between consecutive points; the largest jump is the steepest segment." },
"di-gi-temps#2": { fast: "June, July, August, September are 22, 25, 24, 20 — four months at or above 20.", traps: "(A) 3 drops September, but \"at least 20\" includes 20. (C) 5 adds May, which is 18.", take: "\"At least\" includes the boundary value; \"more than\" excludes it." },
"di-gi-temps#3": { fast: "Average January and July: (2 + 25)/2 = 13.5. April reads 12 on the graph, so the average is greater than April.", traps: "(A) mistakes the ordering. (D) and (E) invent ratios the numbers do not support.", take: "Compute both sides before choosing a comparison word." },
"di-gi-temps#4": { fast: "Add the twelve readings once each: 160. Divide by 12: about 13.3, which is closest to 13°C.", traps: "(D) 14 is a rounding-up slip. (B) 12 comes from dividing by 13. (E) 15 uses only the warm months.", take: "For a mean from a graph, add every point once and divide by the count." },
"di-gi-study#1": { fast: "The dots climb from bottom-left to top-right with one small dip. Positive relationship.", traps: "(C) no relationship needs a flat cloud. (E) is the reflex for a scatter plot; the trend here is plain.", take: "Read the direction of the cloud, not any single pair of points." },
"di-gi-study#2": { fast: "More than 4 hours: 5, 6, 7, 8 hours. Their scores: 80, 79, 88, 90. Two below 85.", traps: "(E) 4 includes the two students at exactly 4 hours. (B) 1 misses one of 79 or 80.", take: "\"More than\" is strict — the boundary value does not count." },
"di-gi-study#3": { fast: "(6, 79) versus (5, 80): the 6-hour student is one point lower.", traps: "(A) follows the overall trend instead of the two actual points. (C) needs equal scores.", take: "For a two-point comparison, read the two points and ignore the trend." },
"di-gi-study#4": { fast: "At most 3 hours: scores 52, 58, 64, 66. Median (58 + 64)/2 = 61.", traps: "(B) 60 is the mean of the four. (A) 58 and (E) 64 are the middle values themselves.", take: "Filter the points by the condition first, then take the median of what remains." },
"di-ta-reps#1": { fast: "Revenue ÷ units: Eli 66/60 = 1.10 leads; Cara and Fay are 0.90.", traps: "(B) Dev has the most revenue but the lowest per unit, 0.60. (E) Hana is 0.80. (A) and (D) tie at 0.90, below Eli.", take: "A ratio the table does not print must be computed — but only for the plausible rows." },
"di-ta-reps#2": { fast: "Sorted units: 60, 90, 110, 120, 130, 150, 170, 200. Middle pair 120 and 130 → 125.", traps: "(A) 120 and (C) 130 are the two middle values. (D) 135 and (E) 140 are off by a slot.", take: "Sort, then average the two middle rows for an even count." },
"di-ta-reps#3": { fast: "Add the two reps per region: North 177, South 196, East 219, West 202. East is highest by 17.", traps: "(D) West is second at 202. (B) South 196. (E) no tie exists.", take: "Group rows by the category column and add before comparing." },
"di-ta-reps#4": { fast: "Only (C) survives: Eli's 66/12 = 5.5 per customer beats every other rep (next best 4.5).", traps: "(A) Fay's 110 is below Hana's 170. (B) Dev has the most customers, Hana the most revenue. (D) South 280 beats North 210. (E) mean is 99.25.", take: "\"Every\" and \"the most\" claims fall to a single counterexample; find it in the table." },
"di-twopart-gaps#1": { fast: "All pens would be $24; each notebook swap adds $3; $15 extra means 5 notebooks, 7 pens.", traps: "(B) (5, 7) swaps the two counts. (C) 8 pens + 4 notebooks is $36. (E) 9 + 3 is $33.", take: "Assume all one item, then count the swaps needed to reach the real total." },
"di-twopart-gaps#2": { fast: "Closing speed 150 km/h, so 2 hours; the 80 km/h train covers 160 km.", traps: "(A) 140 is the slower train's distance. (E) 150 is the closing speed, not a distance. (C) 3 hours is 300/100.", take: "Approaching objects: add the speeds; then each distance is its own speed × the shared time." },
"di-twopart-gaps#3": { fast: "Net rate is fill minus drain: 1/6 − 1/9 = 3/18 − 2/18 = 1/18 of the tank per hour, so 18 hours to fill.", traps: "(C) 5/18 adds the rates. (E) pairs the right rate with the wrong time. (B) and (D) are wrong on both counts.", take: "A drain is a negative rate; subtract it before inverting to get the time." },
"di-twopart-gaps#4": { fast: "Fix E last and the D–A pair together; B must come before D and C after A. That forces B, D, A, C, E.", traps: "(A) (D, A) puts the pair first, but B must precede A. (B) (B, D) has D fourth, but D is second.", take: "Anchor the fixed pair and the fixed last place, then slot the rest." },
"di-twopart-gaps#5": { fast: "Permitted: P–S, Q–R. Prohibited: P–R, Q–S. Only (E) puts a permitted pair first and a prohibited pair second.", traps: "(C) and (D) list two permitted pairs. (A) and (B) put a prohibited pair in the permitted column.", take: "Write out every combination and mark it before reading the pairs offered." },
"di-twopart-gaps#6": { fast: "Only (0, 4) reaches 60 packages within $200,000; every mix with a van breaks the budget.", traps: "(A) 8 vans carry 64 but cost $240,000. (C), (D), (E) all exceed $200,000.", take: "Two constraints: test each candidate against both, and expect exactly one survivor." },
"quant-numberline-ex#19": { fast: "Exponents 4, 3, 5, 4, 4 — the lone 5 wins before you look at the decimals.", traps: "(B) 9.9 × 10³ has the largest decimal and the smallest value. (D) 8.7 × 10⁴ is the best of the exponent-4 group.", take: "In scientific notation, compare exponents first and decimals only to break a tie." },
"quant-numprops-more#1": { fast: "Factorize: 12 = 2²·3 and 18 = 2·3². Take every prime at its highest power: 2²·3² = 36.", traps: "(E) 72 doubles the answer. (C) 24 is 2³·3, the LCM of 8 and 12. (A) 6 is the GCD.", take: "LCM: every prime at its highest power. GCD: shared primes at their lowest." },
"quant-numprops-more#2": { fast: "Factorize: 48 = 2⁴·3 and 72 = 2³·3². Take each shared prime at its lowest power: 2³·3 = 24.", traps: "(B) 12 is a common divisor but not the greatest. (E) 48 divides 72? No. (C) 16 does not divide 72.", take: "The GCD is the biggest number that divides both — check by dividing." },
"quant-numprops-more#3": { fast: "For two numbers, LCM × GCD equals their product: 180 × 6 = 1080, and 1080 ÷ 30 = 36.", traps: "(E) 60 is 180 ÷ 3. (A) 24 and (D) 45 are factors of 180 that fail the GCD test with 30.", take: "For two numbers, lcm × gcd = a × b — the fastest route to a missing number." },
"quant-numprops-more#4": { fast: "They coincide every LCM(8, 12) = 24 minutes, so the next joint ring is 24 minutes after noon: 12:24.", traps: "(D) 12:48 is twice the LCM. (E) 1:36 is the product 96 minutes. (A) 12:20 is 8 + 12.", take: "Repeating events coincide at multiples of the LCM of their periods." },
"quant-numprops-more#5": { fast: "gcd(72, 120) = 24. It divides both; 36 and 48 do not divide 120.", traps: "(D) 36 divides 72 but not 120. (E) 48 divides neither evenly. (A) 12 works but is not the largest.", take: "Largest tile with no cutting = GCD of the dimensions." },
"quant-numprops-more#6": { fast: "Primes needed: 2² (from 4), 3 (from 6 or 15), 5 (from 15): 60.", traps: "(E) 360 is the raw product. (C) 120 and (D) 180 are multiples of 60, not the smallest. (A) 30 is not divisible by 4.", take: "The LCM of several numbers takes each prime once, at its highest power." },
"quant-numprops-more#7": { fast: "n must be a multiple of both 12 and 20, so n = lcm(12, 20) = 60, and the question asks for n/4 = 15.", traps: "(E) 30 is n/2. (A) 5 is n/12. (D) 20 is one of the divisors.", take: "Answer the question asked — the LCM was only the first step." },
"quant-numprops-more#8": { fast: "Shared primes 2 and 3 at lower powers: 2²·3² = 36. Ignore the 5 and the 7.", traps: "(E) 72 uses 2³. (C) 18 uses 2¹. (A) 6 uses the first powers only.", take: "GCD from factorizations: lower power of each shared prime, unshared primes dropped." },
"quant-numprops-more#9": { fast: "Adding 1 to an odd number always gives an even one. Test n = 3: n + 1 = 4, while the other choices give 5, 7, 9 and 9.", traps: "(B) n + 2 keeps the parity. (C) 2n + 1 is always odd. (D) and (E) are odd × odd.", take: "Adding 1 flips parity; adding 2 keeps it." },
"quant-numprops-more#10": { fast: "Even sum means same parity. x = 3, y = 5 kills I and III; II survives every pair.", traps: "(D) keeps I, but 3 + 5 is even without either being even. (E) keeps III, but 3 × 5 is odd.", take: "Same parity ⟹ their difference is even; nothing more is forced." },
"quant-numprops-more#11": { fast: "n and n + 1 are consecutive, so one of them is even, and any product with an even factor is even.", traps: "(D) multiple of 4 fails at 2 × 3 = 6. (E) never a square. (C) never prime beyond n = 1.", take: "The product of k consecutive integers is divisible by k!." },
"quant-numprops-more#12": { fast: "a = 2, b = 3: a + b = 5, ab = 6, a² + b = 7. I and III are odd.", traps: "(E) includes ab, but an even factor makes any product even. (A) drops III, which is even + odd.", take: "Even × anything is even; even + odd is odd." },
"quant-numprops-more#13": { fast: "Three in a row always include a multiple of 2 and a multiple of 3, so 6 always divides.", traps: "(A) 4 fails for 1·2·3 = 6. (D) 8 fails for the same reason. (E) 9 fails for 2·3·4 = 24.", take: "k consecutive integers: product divisible by k!, and only that is guaranteed." },
"quant-numprops-more#14": { fast: "(p − 1)(p + 1) are consecutive evens; one is a multiple of 4, so the product is a multiple of 8. p = 3 gives exactly 8.", traps: "(A) 3, (C) 6 and (E) 12 all fail at p = 3, where p² − 1 = 8. (B) 5 fails at p = 3 too.", take: "Test the smallest allowed prime; it is usually the one that breaks the tempting choices." },
"quant-numprops-more#15": { fast: "31, 37, 41, 43, 47. Cross out multiples of 3 (33, 39, 45) and 49 = 7².", traps: "(D) 6 counts 49. (B) 4 misses one of 41/43. (E) 7 counts 33 or 39.", take: "To test primes under 100, divide by 2, 3, 5 and 7 only." },
"quant-numprops-more#16": { fast: "Odd sum from two primes forces one of them to be 2; the other is 23; product 46.", traps: "(E) 100 is 25², a guess at squaring. (C) 66 is 6 × 11, from ignoring that both must be prime.", take: "An odd total from two primes means 2 is one of them." },
"quant-numprops-more#17": { fast: "4d + 6 = 2.5(d + 6) gives d = 6, so Maria is 24. Check: 30 and 12 in six years.", traps: "(D) 36 answers with d = 9. (A) 20 is 24 − 4. (C) 30 is Maria's age in six years.", take: "Write both ages now, add the same years to both, then apply the ratio." },
"quant-numprops-more#18": { fast: "Write the father as 60 − s, then ten years ago: 50 − s = 3(s − 10). That gives 4s = 80, so the son is 20 and the father 40.", traps: "(E) 40 is the father's age. (B) 18 and (D) 25 are near misses from a slip in 50 − s = 3s − 30. (A) 15 halves the difference.", take: "Use the sum to remove one variable before applying the time shift." },
"quant-numprops-more#19": { fast: "Reversing changes the value by 9 × (difference of the digits): 27 means the digits differ by 3. With a sum of 9: 6 and 3, so 63.", traps: "(A) 36 is the reversed number. (E) 72 has digits summing to 9 but differing by 5. (C) 54 differs by 1.", take: "Number minus its reversal is always 9 × (tens − units)." },
"rc-ss-impressionism#6": { fast: "Light is \"the sole subject\" and the object is \"immaterial\"; ideas and emotions are excluded. So the subject is the light on the stone.", traps: "(A) and (D) are the religious ideas and emotions the passage says the movement excluded. (C) and (E) are never connected to Impressionism at all.", take: "Application questions apply the passage's stated principle to a new case — find the principle first." },
"rc-g1-08#20": { fast: "The shape is: a measure meant to control a group becomes that group's way out. Only the certification story (B) has that reversal.", traps: "(A), (D) and (E) are backfires, but the controlled party does not turn the tool to its own use. (C) is a policy that simply works.", take: "For analogies, match the structure of the outcome, not the subject matter." },
"rc-700-sanandreas#5": { fast: "The last sentence asks whether pressurised water is in the fault. The next study checks for it.", traps: "(A) and (C) repeat experiments already described. (D) and (E) are unrelated to the missing heat.", take: "An extension question about \"next steps\" points at the passage's final unanswered question." },
"rc-ss-seals#4": { fast: "Small size → fat runs out → must forage during lactation. A small new phocid gets the same prediction.", traps: "(A) is the fasting strategy the passage says small seals cannot sustain. (E) is the otariid lactation range. (C) reverses the size logic.", take: "When a passage explains a trait by a cause, a new case with the same cause gets the same trait." },
"rc-700-housework#6": { fast: "Cowan: devices cut the helpers' work and raised the standard, so the home worker did more. Apply that to a new device — (C).", traps: "(A) is the myth Cowan attacked. (B) contradicts the helpers point. (D) and (E) are inventions.", take: "Predictions attributed to an author must follow the mechanism the author described." },
"rc-g1-04#10": { fast: "Total non-interference lets forest replace the shrub the rhinos need — the passage's own warning. That policy helps least.", traps: "(A) is the helpful opposite. (B) and (D) address the human harms the passage lists. (C) is the method scientists already use.", take: "\"Least helpful\" questions usually point at the passage's counter-intuitive warning." },
"di-msr-scholarship#1": { fast: "Route 1 needs GPA ≥ 3.5 and income ≤ 60k; route 2 needs GPA ≥ 3.8. Amy, Bo, Eve, Finn pass; Cal and Dana fail. Four.", traps: "(B) 3 drops Finn, whose $60,000 is at the limit, not over it. (D) 5 admits Dana, whose 3.7 falls short of 3.8 and whose income is over.", take: "\"At most\" includes the boundary; \"or\" means either route suffices." },
"di-msr-scholarship#2": { fast: "Bo fails the income test and passes on GPA alone. Eve passes both ways, so she is not \"only\" the GPA route.", traps: "(D) Eve qualifies by both routes. (C) Dana qualifies by neither. (A) and (E) qualify by the income route.", take: "\"Only because of\" means the other route fails for that applicant." },
"di-msr-scholarship#3": { fast: "Renewal needs 3.3: the 3.2 scholar fails, the 3.6 passes. Exactly one — (B).", traps: "(E) reads \"at most $60,000\" as exclusive. (A) forgets the $10,000 budget funds two. (D) three awards need $12,000.", take: "Check the boundary values and the budget arithmetic before trusting an impression." },
"di-msr-scholarship#4": { fast: "Budget funds two. Eligible GPAs: Bo 3.9, Eve 3.85, Amy 3.6, Finn 3.5. Top two: Bo and Eve.", traps: "(C) Dana's 3.7 would rank third but she is not eligible. (A) and (D) put Amy above Eve.", take: "Filter for eligibility first, then rank." },
"di-msr-scholarship#5": { fast: "Two new awards ($8,000) plus one renewal ($4,000) = $12,000.", traps: "(D) $16,000 renews the 3.2 scholar, who fails the 3.3 rule. (A) $8,000 forgets the renewal.", take: "Payments = new awards + qualifying renewals, all at the same rate." },
"di-msr-scholarship#6": { fast: "Both routes need at least 3.5, so every eligible applicant has 3.5 or more. Dana (3.7, ineligible) kills (A).", traps: "(A) reverses the direction of the rule. (C) is refuted by Dana. (D) fails on the 3.2 GPA.", take: "Distinguish \"eligible → GPA ≥ 3.5\" from \"GPA ≥ 3.5 → eligible\"." },
"di-msr-ferry#1": { fast: "Last usable return is 15:00 (back 15:50). Four hours before that means arriving by 11:00; the 10:00 boat arrives 10:50.", traps: "(C) 12:00 arrives 12:50 and leaves only 2 h 10 min. (D) and (E) cannot get back in time at all.", take: "Work backwards from the deadline, and count the crossing time both ways." },
"di-msr-ferry#2": { fast: "The 17:00 return arrives 17:50, so the 15:00 is the last that makes 17:00 — (D).", traps: "(B) 14 is not under 12. (C) bicycles get no day-return discount. (A) the 12:00 out can still return by 15:50.", take: "Read age limits and discount rules literally; \"under 12\" excludes 12 and up." },
"di-msr-ferry#3": { fast: "Three adult day-returns (the 14-year-old is an adult) $60, one child $11, bike $6: $77.", traps: "(A) $71 charges the 14-year-old as a child. (C) $83 adds a bike day-return that does not exist. (E) $92 is the all-singles total.", take: "Classify every traveller by the fare rules before you multiply." },
"di-msr-ferry#4": { fast: "Singles total $92; day-returns $77; saving $15. Or: $4 per adult × 3 plus $3 for the child.", traps: "(B) $11 forgets one adult's saving. (D) $19 adds a bike saving that does not exist. (A) $8 counts only two adults.", take: "Savings per ticket type × number of that type, and the bike saves nothing." },
"di-msr-ferry#5": { fast: "The 10:00 boat lands at 10:50; the 15:00 boat leaves the island. From 10:50 to 15:00 is 4 hours 10 minutes.", traps: "(D) 5 hours ignores the 50-minute crossing. (C) 4 h 50 subtracts the crossing twice. (A) 4 hours rounds it away.", take: "Time on the island runs from arrival, not departure." },
"di-gi-adverts#1": { fast: "The dots climb from (2, 30) to (10, 63) with one tiny dip: positive.", traps: "(C) invents a threshold; the rise is visible across the whole range. (B) needs a flat cloud.", take: "Judge the direction of the whole cloud, not a single pair of points." },
"di-gi-adverts#2": { fast: "Spend strictly above 5 leaves 6, 7, 8 and 10. Of their sales — 48, 52, 55, 63 — only 48 and 52 are below 55. Two stores.", traps: "(C) 3 counts the store at exactly 55. (D) 4 includes spend 5 or all four high spenders.", take: "\"More than\" and \"below\" are strict; boundary points do not count." },
"di-gi-adverts#3": { fast: "30 ÷ 2 = 15 beats every other ratio; the ratio keeps falling as spend rises.", traps: "(E) the biggest spender sells the most in total but only 6.3 per unit of spend. (C) is 8.", take: "Highest ratio means steepest line from the origin — usually a small-x point." },
"di-gi-adverts#4": { fast: "Read the two named points: the $5,000 store sold 40 and the $4,000 store sold 41, so the answer is less than.", traps: "(A) follows the overall trend rather than the two actual points. (C) needs equal sales.", take: "For two named points, read the points, not the trend." },
"di-gi-adverts#5": { fast: "Compare the two ends of the range: sales go from 30 to 63, a factor of about 2.1, so they roughly double.", traps: "(D) triple would need about 90. (B) ignores the rise. (E) quadruple would be 120.", take: "Compare the ends of the range and express it as a factor." },
"di-gi-website#1": { fast: "Add all seven bars for 116 thousand; Saturday plus Sunday is 44 thousand; 44/116 is about 38 percent.", traps: "(B) 34% uses a total of 130. (D) 42% divides 44 by 105. (E) 46% is the weekend share of weekdays alone.", take: "Share questions: add every bar first." },
"di-gi-website#2": { fast: "Friday 18 to Saturday 24 is a rise of 6 on a base of 18 — exactly one third, so about 33 percent.", traps: "(A) 25% divides by 24, the later day. (D) 50% is 6/12. (C) 40% is 6/15.", take: "Percent change uses the earlier value as the base." },
"di-gi-website#3": { fast: "Median 15 (fourth of seven sorted); mean 116/7 ≈ 16.6. Median is less.", traps: "(C) greater than confuses a right-skewed week: the big weekend days lift the mean, not the median. (B) equal would need symmetry.", take: "A few large values pull the mean above the median." },
"di-gi-website#4": { fast: "The busiest day is Saturday: 300 orders on 24 thousand visits, and 300 ÷ 24 = 12.5 orders per thousand visits.", traps: "(C) 15 divides by 20, Sunday's visits. (A) 10 divides 240 by 24. (D) 20 is 300/15.", take: "Identify the busiest day first, then take that day's two figures." },
"di-gi-website#5": { fast: "Friday 240/18 ≈ 13.3 is the highest orders-per-thousand; every other day sits at 12.5–12.9.", traps: "(D) Saturday has the most orders but only 12.5 per thousand. (A) Wednesday's 12.9 is second.", take: "Per-visit rate is the slope from the origin; the point highest above that line wins." },
"di-gi-website#6": { fast: "Orders rise with visits at every step and the points lie near a line: positive and linear.", traps: "(D) invents a reversal; Saturday has both the most visits and the most orders. (E) seven points show the pattern plainly.", take: "Linear means the points hug a straight line; check the busiest day too." },
"di-ta-athletics#1": { fast: "Medals over events: Kim 3/4 = 0.75 is far ahead of the field; Mia 4/7 ≈ 0.57 is the only other above 0.5.", traps: "(C) Mia has the most medals but more events. (E) Oli entered the most events and has the lowest ratio.", take: "Ratios reward a small denominator; do not confuse the most with the best rate." },
"di-ta-athletics#2": { fast: "Lou 33/6 = 5.5 edges Oli 50/9 ≈ 5.56 for the lowest points per event.", traps: "(B) Oli is a close second. (C) Pia's 22/3 ≈ 7.3 is mid-table. (D) and (E) are near 7.6.", take: "When two ratios are close, compute both to two decimals." },
"di-ta-athletics#3": { fast: "Juniors total 38 + 40 + 59 + 22 = 159; the club totals 348. 159/348 ≈ 45.7%, which rounds to 46%.", traps: "(E) 50% assumes an even split. (A) 42% and (B) 44% under-count a Junior.", take: "Group share: add the group, add everyone, divide." },
"di-ta-athletics#4": { fast: "Add each group's medals: Seniors 3 + 1 + 2 + 2 = 8, Juniors 2 + 3 + 4 + 1 = 10. Reduce 8 : 10 to 4 : 5.", traps: "(D) 5:4 reverses the order asked. (B) 2:3 miscounts a medal. (A) 1:1 assumes parity.", take: "Ratios are ordered; read which group comes first in the question." },
"di-ta-athletics#5": { fast: "Lou: 33 points on one medal = 33 per medal, the highest by far.", traps: "(C) Oli 25 is second. (B) Noor 22.5. (E) Pia also has one medal but only 22 points.", take: "A single medal makes the per-medal ratio large — check the one-medal rows first." },
"di-ta-athletics#6": { fast: "Senior points sorted: 33, 45, 50, 61. Middle two average to 47.5.", traps: "(A) 45 and (C) 50 are the middle values themselves. (D) 52 is near the mean of the four (47.25).", take: "Filter to the group, sort, then take the median." },
"di-ta-athletics#7": { fast: "Mia's 4 medals beat every Senior's (max 3) — (C). Each other claim has a counterexample in the table.", traps: "(B) Oli entered the most events; Jak has the most points. (D) Juniors 10 beat Seniors 8. (E) mean is 43.5.", take: "Test universal claims by hunting for the one row that breaks them." },
"di-twopart-tradeoffs#1": { fast: "Minimums use 3 cakes (6 h) and 3 pies (3 h); the spare hour goes to a fourth pie: (3, 4), profit 34.", traps: "(A) (3, 3) wastes an hour. (C) (4, 2) breaks the pie minimum. (D) and (E) break the cake minimum.", take: "Satisfy the minimums, then spend leftover capacity on the option that fits." },
"di-twopart-tradeoffs#2": { fast: "(2, 3) fills all 12 hours for 31 points; (1, 4) gives 28, (3, 1) gives 29.", traps: "(B) (1, 4) leaves an hour unused and scores 28. (D) and (E) violate the at-least-one rule.", take: "Enumerate the feasible pairs and compare — there are rarely more than four." },
"di-twopart-tradeoffs#3": { fast: "X: 30 minutes, $13. Y: 36 minutes, $12. Cheaper Y, faster X.", traps: "(B) has the two swapped. (A) forgets the toll makes X dearer. (E) the costs differ by $1.", take: "Compute time and cost separately; the winner of one is often the loser of the other." },
"di-twopart-tradeoffs#4": { fast: "Price both plans at each level. 10 GB: A $40 versus B $45. 20 GB: A $60 versus B $50. So A first, then B.", traps: "(A) keeps A at 20 GB, where its $2 overage bites. (D) keeps B at 10 GB, where its $45 base loses.", take: "Price both plans at each usage level; the cheaper plan changes with usage." },
"di-twopart-tradeoffs#5": { fast: "Low: 98 good, 2 bad. High: 138 good, 12 bad. More good: High. Fewer bad: Low.", traps: "(D) High for both forgets 12 defectives beat 2. (A) Low for both forgets 138 beats 98.", take: "Good = output × (1 − rate); defective = output × rate — two different comparisons." },
"di-twopart-tradeoffs#6": { fast: "Q and S form a block with Q first. P cannot open, so the block opens; P must precede R, giving Q, S, P, R.", traps: "(B) (Q, P) puts P last, but P must precede R. (C) S cannot be first because Q is immediately before it.", take: "Fix the blocks and the forbidden positions; usually one order survives." },
"di-twopart-tradeoffs#7": { fast: "Engineer → certified → at least a year, so engineers have a year. The reverse direction is never given, so long service need not mean certified.", traps: "(D) has the pair the wrong way round. (E) pairs two must-be-trues. (B) and (C) start with false statements.", take: "Chains of \"all\" statements run one way; the converse could be false." },
/* __EXPL__ */
});
